#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

REPO_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO_ROOT"
RECEIPT_DIR="packages/portal/.facebook-setup-receipts"
mkdir -p "$RECEIPT_DIR"
ENV_FILE="${FACEBOOK_SETUP_ENV_FILE:-$RECEIPT_DIR/setup.env}"

banner "Facebook Instant Games evidence setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "App and business prerequisites"
say "This records prerequisites; it does not claim Meta approval or change the progress tracker."
open_url "https://developers.facebook.com/apps/"
step "Create or select the new Instant Games app owned by the intended business. Do not reuse historical Riddle Quest Facebook credentials."
step "Record the new numeric Meta app ID. Leave Business verification and Approved Partner approval deferred until the final release gate."
ask FACEBOOK_APP_ID "Paste the new Meta app ID (non-secret):"
if [[ ! "$FACEBOOK_APP_ID" =~ ^[0-9]{5,32}$ ]]; then
  warn "the app ID must contain 5–32 decimal digits"
  exit 1
fi
write_env FACEBOOK_APP_ID "$FACEBOOK_APP_ID"
pause "Confirm the app is new and the deferred approvals are recorded in the tracker, then press Enter."

stage "App configuration and public URLs"
say "Use the labels shown by the current Meta App Dashboard. Meta can rename or move settings; do not guess a replacement field."
open_url "https://developers.facebook.com/apps/$FACEBOOK_APP_ID/"
step "Configure Instant Games SDK v8, Zero Permissions, age category 13+, role/test accounts, and the exact game domains."
step "Configure the public privacy-policy URL and the signed data-deletion callback/status URLs. Open every URL in a private browser window and confirm HTTPS success."
step "Save a redacted settings export or screenshots outside the repository for second-person review."
ask FACEBOOK_GAME_ORIGINS "Paste exact comma-separated HTTPS game origins:"
ask FACEBOOK_DELETION_STATUS_BASE_URL "Paste the public HTTPS deletion status base URL:"
if [[ ! "$FACEBOOK_GAME_ORIGINS" =~ ^https:// ]] || [[ ! "$FACEBOOK_DELETION_STATUS_BASE_URL" =~ ^https:// ]]; then
  warn "origins and deletion status URL must begin with https://"
  exit 1
fi
write_env FACEBOOK_GAME_ORIGINS "$FACEBOOK_GAME_ORIGINS"
write_env FACEBOOK_DELETION_STATUS_BASE_URL "$FACEBOOK_DELETION_STATUS_BASE_URL"

stage "New server secrets"
warn "Never paste either secret into this wizard, a shell argument, GitHub, source control, a screenshot, or a fixture."
step "In the Meta dashboard, issue a new app secret for this app. It must differ from every historical repository value."
step "In a private terminal, run: pnpm dlx firebase-tools@15.25.1 functions:secrets:set FACEBOOK_APP_SECRET --project riddle-quest-ec2b2"
step "Generate an independent random 32-byte-or-longer UID HMAC key, then set it with: pnpm dlx firebase-tools@15.25.1 functions:secrets:set FACEBOOK_UID_SECRET --project riddle-quest-ec2b2"
step "Record only Secret Manager version numbers, actor, UTC time, and least-privilege review outside the repository. Revoke superseded versions after deployment verification."
pause "Press Enter only after both new secret versions exist and no secret value has been copied into the repository."

stage "Real capability and device matrix"
say "Upload only an audited non-production test artifact. Public release remains forbidden until every Phase 0 gate passes."
step "Against the exact ZIP hash, test Facebook web, real iOS, and real Android with multiple role accounts."
step "Capture SDK initialize/loading/start ordering, Firebase/App Check connectivity, effective CSP hosts, overlays, contexts, matchmaking, tournaments, pause/resume, ads, IAP, and recovery."
step "Test notification opt-in, D1/D3/D7 replacement/cancellation, race alerts, and deep links. Record unsupported APIs explicitly; never substitute a browser mock for device evidence."
pause "Press Enter after the sanitized matrix names the device/OS/app role, UTC time, ZIP SHA-256, and pass/fail result for every capability."

stage "Sanitized contract fixtures"
warn "Fixtures must contain no raw player IDs, access tokens, secrets, names, photos, purchase tokens, or reusable assertions."
step "Capture identity, purchase, recovery, refund/webhook, notification, tournament, context, and lifecycle payload shapes from the real test app."
step "Preserve signature bytes separately in owner-only evidence when automated tamper verification requires them; commit only irreversibly sanitized deterministic fixtures."
step "Document provenance, SDK version, capture time, redactions, and the exact app/ZIP hash for each fixture."
pause "Press Enter after a second person has checked that the fixture set is both useful and non-sensitive."

stage "Evidence and tracker handoff"
step "Store approval records, dashboard exports, network logs, device captures, and secret-version evidence outside the repository in access-controlled storage."
step "For each P0 row, add a redacted evidence link or reproducible command and its UTC timestamp to docs/facebook-instant-games-progress.html."
step "Run: pnpm check:facebook-progress"
step "Mark a row Complete only after its acceptance criteria pass. Keep P0-01 deferred until final approval, and keep any failed or absent external proof Blocked/In Progress."
step "Before draft upload, run the exact-byte handoff documented in docs/facebook-instant-games-operations.md."
# ──────────────────────────────────────────────────────────────────────────

finish
